\begin{proposition}[隐函数一阶求导]
若方程 $F(x,y)=0$ 在某区间上确定可导函数 $y=y(x)$，且 $F$ 有连续偏导数、$F_y(x,y)\neq0$，则
\[
y'=-\frac{F_x}{F_y},
\]
其中右端在 $(x,y(x))$ 处取值。
\end{proposition}
\begin{proofdetail}
由恒等式 $F(x,y(x))\equiv0$ 对 $x$ 求导。 复合函数求导给出
\[
F_x(x,y(x))+F_y(x,y(x))y'(x)=0.
\]
由于 $F_y(x,y(x))\neq0$，移项并相除得到公式。
\end{proofdetail}

\begin{example}[隐函数一阶导数]
由方程 $x^2+xy+y^2=3$ 确定 $y=y(x)$，求 $y'$。
\end{example}
\begin{solution}
两边对 $x$ 求导：
\[
2x+y+xy'+2yy'=0.
\]
整理得
\[
y'=-\frac{2x+y}{x+2y}.
\]
该公式在 $x+2y\neq0$ 的点成立。
\end{solution}

\begin{example}[先说明隐函数再求导]
设方程
\[
\sqrt{y}+x^2-1=0
\]
在 $|x|<1$ 附近确定函数 $y=y(x)$。 用两种方法求 $y'$。
\end{example}
\begin{solution}
方法一：先解出显函数。 由方程得
\[
\sqrt{y}=1-x^2.
\]
当 $|x|<1$ 时右端为正，故
\[
y=(1-x^2)^2.
\]
于是
\[
y'=2(1-x^2)(-2x)=-4x(1-x^2).
\]

方法二：直接对原方程求导。 注意
\[
\frac{\dd}{\dd x}\sqrt{y}
=\frac{1}{2\sqrt{y}}y',
\]
因此
\[
\frac{y'}{2\sqrt{y}}+2x=0,
\qquad
y'=-4x\sqrt{y}.
\]
再代入 $\sqrt{y}=1-x^2$，得
\[
y'=-4x(1-x^2).
\]
两种方法结果一致。
\end{solution}

\begin{example}[隐函数二阶导数]
设 $x^2+y^2=1$ 在点附近确定 $y=y(x)$，求 $y''$。
\end{example}
\begin{solution}
一阶求导得
\[
2x+2yy'=0,\qquad y'=-\frac{x}{y}\quad(y\neq0).
\]
对 $2x+2yy'=0$ 再求导：
\[
2+2(y')^2+2yy''=0.
\]
故
\[
y''=-\frac{1+(y')^2}{y}=-\frac{1+x^2/y^2}{y}
=-\frac{x^2+y^2}{y^3}=-\frac1{y^3}.
\]
\end{solution}

\begin{example}[隐函数切线]
求曲线
\[
xy-\ee^x+\ee^y=0
\]
在点 $(0,0)$ 处的切线方程。
\end{example}
\begin{solution}
把 $y$ 看成 $x$ 的函数，对方程两边求导，得
\[
y+xy'-\ee^x+\ee^y y'=0.
\]
整理得
\[
(x+\ee^y)y'=\ee^x-y,\qquad
y'=\frac{\ee^x-y}{x+\ee^y}.
\]
在 $(0,0)$ 处，
\[
y'(0)=\frac{1-0}{0+1}=1.
\]
因此切线方程为 $y=x$。
\end{solution}

